function useLanguage() {
  const [lang,setLang] = useState<Language>(()=>localStorage.getItem('sales-lang') === 'en' ? 'en' : 'ar');
  useEffect(()=>{ document.documentElement.lang=lang; document.documentElement.dir=lang==='ar'?'rtl':'ltr'; localStorage.setItem('sales-lang',lang); },[lang]);
  return { lang, setLang, t:(key:string)=>words[key]?.[lang==='ar'?0:1] || key };
}
type Context = ReturnType<typeof useLanguage>;
const money=(v:string|number,lang:Language)=>new Intl.NumberFormat(lang==='ar'?'ar-EG':'en-US',{maximumFractionDigits:2}).format(Number(v)||0);
const dateText=(v:string,lang:Language)=>{ const d=new Date(v); return Number.isNaN(d.getTime())?v:new Intl.DateTimeFormat(lang==='ar'?'ar-EG':'en-GB',{day:'numeric',month:'short',year:'numeric'}).format(d); };
const errText=(e:unknown)=>e instanceof Error?e.message:String(e);
function authError(e:unknown,lang:Language,action:'login'|'password'|'session'='login'){
  if(e&&typeof e==='object'&&'status' in e&&typeof e.status==='number'){
    if(action==='login'&&e.status===401)return lang==='ar'?'رقم الموظف أو كلمة المرور غير صحيحة، أو الحساب غير نشط.':'Invalid employee ID or password, or the account is inactive.';
    if(action==='login'&&e.status===429)return lang==='ar'?'محاولات كثيرة. حاول لاحقاً.':'Too many attempts. Try again later.';
    if(action==='password'&&e.status===400)return lang==='ar'?'تعذر تغيير كلمة المرور. تحقق من الكلمة الحالية وشروط الكلمة الجديدة.':'Could not change password. Check your current password and the new password requirements.';
    if(action==='password'&&e.status===401)return lang==='ar'?'انتهت الجلسة. أعد تحميل الصفحة وسجّل الدخول.':'Session expired. Reload and sign in again.';
  }
  return lang==='ar'?'خدمة تسجيل الدخول غير متاحة حالياً. حاول مجدداً لاحقاً.':'Sign-in service is unavailable. Please try again later.';
}
const nullNum=(value:string)=>value.trim()?Number(value):null;
function Button({children,onClick,kind='',type='button',disabled,testId}: {children:ReactNode;onClick?:()=>void;kind?:string;type?:'button'|'submit';disabled?:boolean;testId?:string}) {return <button data-testid={testId} className={`btn ${kind}`} type={type} onClick={onClick} disabled={disabled}>{children}</button>}
function Field({label,value,onChange,type='text',required=false,placeholder='',options,testId,min,step}: {label:string;value:string|number;onChange:(v:string)=>void;type?:string;required?:boolean;placeholder?:string;options?:{value:string;label:string}[];testId?:string;min?:string;step?:string}) { return <div className="field"><label>{label}{required?' *':''}</label>{options?<select data-testid={testId} value={value} onChange={e=>onChange(e.target.value)} required={required}>{options.map(o=><option key={o.value} value={o.value}>{o.label}</option>)}</select>:<input data-testid={testId} value={value} onChange={e=>onChange(e.target.value)} type={type} required={required} placeholder={placeholder} min={min} step={step}/>}</div> }
function PageHead({ctx,title,desc,action}: {ctx:Context;title:string;desc:string;action?:ReactNode}) {return <div className="page-head"><div><div className="eyebrow">{ctx.t('workspace')} / {title}</div><h1 className="page-title">{title}</h1><p className="page-desc">{desc}</p></div>{action}</div>}
function StateView({loading,error,empty,ctx,retry,children}: {loading:boolean;error:boolean;empty:boolean;ctx:Context;retry:()=>void;children:ReactNode}) {
  if(loading) return <div className="panel panel-pad" aria-busy="true"><div className="skeleton" style={{width:'37%'}}/><div className="skeleton"/><div className="skeleton"/><div className="skeleton" style={{width:'72%'}}/></div>;
  if(error) return <div className="panel empty"><div className="empty-icon"><CircleAlert size={23}/></div><h3>{ctx.t('error')}</h3><Button onClick={retry}>{ctx.t('retry')}</Button></div>;
  if(empty) return <div className="empty"><div className="empty-icon"><Boxes size={23}/></div><h3>{ctx.t('noRecords')}</h3><p>{ctx.t('noRecordsDesc')}</p></div>;
  return <>{children}</>;
}
function Modal({title,onClose,children}: {title:string;onClose:()=>void;children:ReactNode}) {return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}><div className="modal" role="dialog" aria-modal="true" aria-label={title}><div className="modal-head"><h2>{title}</h2><button data-testid="button-close-dialog" className="icon-button" onClick={onClose} aria-label="Close"><X size={19}/></button></div>{children}</div></div>}
function LoginScreen({ctx,onLogin,forced,initialEmployee}: {ctx:Context;onLogin:(employee:Employee)=>void|Promise<void>;forced?:boolean;initialEmployee?:Employee}) {
  const [employeeId,setEmployeeId]=useState(''); const [password,setPassword]=useState(''); const [current,setCurrent]=useState(''); const [next,setNext]=useState(''); const [confirm,setConfirm]=useState(''); const [error,setError]=useState(''); const [pending,setPending]=useState(false);
  const [passwordChanged,setPasswordChanged]=useState(false);
  const [employee,setEmployee]=useState<Employee|undefined>(initialEmployee);
  useEffect(()=>setEmployee(initialEmployee),[initialEmployee]);
  const change=!passwordChanged&&(forced||employee?.mustChangePassword);
   async function submit(e:FormEvent){e.preventDefault();setError('');if(change&&next!==confirm){setError(ctx.lang==='ar'?'كلمتا المرور غير متطابقتين.':'Passwords do not match.');return}setPending(true);try {if(change){await changePassword({currentPassword:current,newPassword:next},{credentials:'include'});setPasswordChanged(true);setEmployee(undefined);setCurrent('');setNext('');setConfirm('');setPassword('');setEmployeeId('')}else {const result=await login({employeeId,password},{credentials:'include'});setEmployee(result);if(result.mustChangePassword)setPasswordChanged(false);else await onLogin(result)}}catch(e){setError(authError(e,ctx.lang,change?'password':'login'))}finally{setPending(false)}}
  return <div className="auth"><div className="auth-art"><div style={{display:'flex',alignItems:'center',gap:12}}><span className="brand-mark">↗</span><strong>{ctx.t('app')}</strong></div><div><div className="eyebrow" style={{color:'#e3aa72',marginBottom:20}}>FIELD OPERATIONS / 01</div><h1>{ctx.lang==='ar'?'كل وردية. سجل واضح.':'Every shift. A clear record.'}</h1><p>{ctx.t('loginDesc')}</p></div><div className="small" style={{color:'#93b6aa'}}>OPERATIONS / SECURE ACCESS</div></div><div className="auth-form-side"><div className="auth-box"><div style={{display:'flex',justifyContent:'space-between',alignItems:'center'}}><span className="eyebrow">EMPLOYEE PORTAL</span><button data-testid="button-language-login" className="language" onClick={()=>ctx.setLang(ctx.lang==='ar'?'en':'ar')}>{ctx.lang==='ar'?'English':'العربية'}</button></div><h2>{change?ctx.t('changePassword'):ctx.t('welcome')}</h2><p className="muted small">{change?ctx.t('changePasswordDesc'):ctx.t('loginTitle')}</p>{passwordChanged&&<div className="notice" role="status" data-testid="status-password-changed">{ctx.lang==='ar'?'تم تغيير كلمة المرور. تم تسجيل خروجك من جميع الجلسات؛ سجّل الدخول بكلمة المرور الجديدة.':'Password changed. All sessions have been signed out; sign in with your new password.'}</div>}{error&&<div className="notice error" role="alert" data-testid="status-login-error">{error}</div>}<form onSubmit={submit}>{change?<><Field label={ctx.t('currentPassword')} value={current} onChange={setCurrent} type="password" required testId="input-current-password"/><Field label={ctx.t('newPassword')} value={next} onChange={setNext} type="password" required min="12" testId="input-new-password"/><Field label={ctx.t('confirmPassword')} value={confirm} onChange={setConfirm} type="password" required testId="input-confirm-password"/></>:<><Field label={ctx.t('employeeId')} value={employeeId} onChange={setEmployeeId} required testId="input-employee-id"/><Field label={ctx.t('password')} value={password} onChange={setPassword} type="password" required testId="input-password"/></>}<Button type="submit" kind="primary" disabled={pending} testId="button-auth-submit">{pending?ctx.lang==='ar'?'جارٍ المعالجة...':'Working...':change?ctx.t('changePassword'):ctx.t('signIn')} {ctx.lang==='ar'?<ArrowLeft size={15}/>:<ArrowRight size={15}/>}</Button></form><p className="small muted" style={{marginTop:25,display:'flex',alignItems:'center',gap:6}}><ShieldCheck size={14}/>{ctx.t('secure')}</p></div></div></div>
}
function Shell({ctx,employee,children,onLogout}: {ctx:Context;employee:Employee;children:ReactNode;onLogout:()=>void}) {
  const [path]=useLocation();const [compact,setCompact]=useState(false);
  const links=nav.filter(n=>can(employee,n.permission));const higher=links.some(n=>n.management);
  const writePermission:Record<string,Permission>={'/users':'users.manage','/customers':'customers.manage','/branches':'branches.manage','/products':'products.manage','/sales':'sales.write','/attendance':'attendance.write'};
  const displayName=ctx.lang==='ar'?employee.nameAr:employee.nameEn||employee.nameAr;
  const navItem=(n:typeof nav[number],mobile=false)=>{const Icon=n.icon;return <Link key={n.path} href={n.path} data-testid={`link-${n.key}`} className={mobile?path===n.path?'active':'':`nav-link ${path===n.path?'active':''}`} title={ctx.t(n.key)}><Icon size={mobile?20:18} strokeWidth={1.9}/><span className={mobile?'':'hide-compact'}>{ctx.t(n.key)}</span></Link>};
   return <div className="app"><aside className={`sidebar ${compact?'compact':''}`}><div className="brand"><div className="brand-mark">↗</div><div className="hide-compact"><div className="brand-title">{ctx.t('app')}</div><div className="brand-sub">FIELD / OPERATIONS</div></div></div><div className="nav-heading hide-compact">{ctx.t('workspace')}</div><nav>{links.filter(n=>!n.management).map(n=>navItem(n))}</nav>{higher&&<><div className="nav-heading hide-compact">{ctx.t('management')}</div><nav>{links.filter(n=>n.management).map(n=>navItem(n))}</nav></>}<div className="sidebar-footer"><button className="nav-link" data-testid="button-collapse-sidebar" onClick={()=>setCompact(!compact)} style={{width:'100%',border:0,background:'transparent'}}><Menu size={18}/><span className="hide-compact">{ctx.lang==='ar'?'طي القائمة':'Collapse menu'}</span></button><button className="nav-link" data-testid="button-logout" onClick={onLogout} style={{width:'100%',border:0,background:'transparent'}}><LogOut size={18}/><span className="hide-compact">{ctx.t('logout')}</span></button></div></aside><div className="workspace"><header className="topbar"><div><div className="topbar-label">{ctx.t('app')} <span style={{color:'#b4bfb7'}}> / </span> {ctx.t(nav.find(n=>n.path===path)?.key||'home')}</div></div><div className="topbar-actions"><span className="small muted" style={{display:'none'}}>{displayName}</span><button className="language" data-testid="button-switch-language" onClick={()=>ctx.setLang(ctx.lang==='ar'?'en':'ar')}>{ctx.lang==='ar'?'EN / العربية':'AR / English'}</button><span className="avatar" title={displayName}>{displayName.slice(0,2)}</span></div></header><main className="main" data-readonly={writePermission[path]&&!can(employee,writePermission[path])?'true':'false'}>{children}</main></div><nav className="mobile-nav">{links.map(n=>navItem(n,true))}<a href="#" data-testid="link-mobile-logout" onClick={e=>{e.preventDefault();onLogout()}}><LogOut size={20}/><span>{ctx.t('logout')}</span></a></nav></div>;
}
function Home({ctx,employee}: {ctx:Context;employee:Employee}) {
  const q=useGetDashboard({query:{queryKey:getGetDashboardQueryKey(),retry:1}});
  const displayName=ctx.lang==='ar'?employee.nameAr:employee.nameEn||employee.nameAr;
  const figures=[{label:ctx.lang==='ar'?'إجمالي المبيعات':'Sales total',value:q.data?money(q.data.salesTotal,ctx.lang):'—',icon:BarChart3,foot:ctx.lang==='ar'?'من السجلات المرسلة':'From submitted records'}, {label:ctx.lang==='ar'?'تقارير المبيعات':'Sales reports',value:q.data?money(q.data.submittedSales,ctx.lang):'—',icon:ShoppingCart,foot:ctx.lang==='ar'?'تقارير مرسلة':'Submitted reports'}, {label:ctx.lang==='ar'?'المنتجات':'Products',value:q.data?money(q.data.products,ctx.lang):'—',icon:Package,foot:ctx.lang==='ar'?'في الكتالوج':'In catalogue'}, {label:ctx.lang==='ar'?'استثناءات الحضور':'Attendance exceptions',value:q.data?money(q.data.attendanceExceptions,ctx.lang):'—',icon:CircleAlert,foot:ctx.lang==='ar'?'تحتاج إلى مراجعة':'Require attention'}];
  return <><PageHead ctx={ctx} title={`${ctx.t('welcome')}، ${displayName}`} desc={ctx.t('overviewDesc')}/><StateView loading={q.isLoading} error={q.isError} empty={false} ctx={ctx} retry={()=>q.refetch()}><div className="stats">{figures.map((item,i)=><div className="panel stat" key={i} data-testid={`stat-${i}`}><item.icon className="stat-icon" size={19}/><div className="stat-label">{item.label}</div><div className="stat-value mono">{item.value}</div><div className="stat-foot">{item.foot}</div></div>)}</div><div className="dashboard-grid"><div className="panel panel-pad"><div className="panel-heading"><div><span className="eyebrow">SHIFT WORKFLOW</span><h2 style={{marginTop:5}}>{ctx.t('quick')}</h2></div><Activity size={19} color="#448270"/></div><p className="page-desc" style={{marginBottom:14}}>{ctx.t('quickDesc')}</p>{[{path:'/attendance',permission:'attendance.write' as Permission,icon:MapPin,key:'attendance',desc:ctx.lang==='ar'?'سجّل بداية أو نهاية الوردية':'Record your shift in or out'}, {path:'/sales',permission:'sales.write' as Permission,icon:ShoppingCart,key:'sales',desc:ctx.lang==='ar'?'أدخل بنود مبيعات اليوم':'Enter today’s sales lines'}, {path:'/reports',permission:'exports.view' as Permission,icon:FileSpreadsheet,key:'reports',desc:ctx.lang==='ar'?'راجع البيانات وصدّر السجلات':'Review and export records'}].filter(a=>can(employee,a.permission)&&can(employee,nav.find(n=>n.path===a.path)!.permission)).map((a,i)=><div className="action-row" key={a.path}><div style={{display:'flex',alignItems:'center',gap:12}}><div className="action-icon"><a.icon size={17}/></div><div><strong className="small">{String(i+1).padStart(2,'0')} / {ctx.t(a.key)}</strong><div className="small muted">{a.desc}</div></div></div><Link href={a.path} className="btn" data-testid={`link-quick-${a.key}`}>{ctx.lang==='ar'?<ChevronLeft size={16}/>:<ChevronRight size={16}/>}</Link></div>)}</div><div className="panel panel-pad"><div className="panel-heading"><h2>{ctx.lang==='ar'?'لقطة تشغيلية':'Operational snapshot'}</h2><span className="badge">{ctx.t('today')}</span></div>{[{label:ctx.t('users'),value:q.data?.users},{label:ctx.t('customers'),value:q.data?.customers},{label:ctx.t('branches'),value:q.data?.branches}].map(x=><div className="action-row" key={x.label}><span className="muted small">{x.label}</span><strong className="mono">{x.value??'—'}</strong></div>)}<div className="notice" style={{margin:'20px 0 0'}}>{ctx.lang==='ar'?'البيانات المعروضة مأخوذة مباشرة من سجلات النظام.':'Figures shown here come directly from system records.'}</div></div></div></StateView></>;
}

